BEGIN;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES
('a7150000-0000-4000-8000-000000000001','pins-0@example.test','{"provider":"email"}','{"display_name":"User 0"}',now(),now()),
('a7150000-0000-4000-8000-000000000002','pins-1@example.test','{"provider":"email"}','{"display_name":"User 1"}',now(),now()),
('a7150000-0000-4000-8000-000000000003','pins-2@example.test','{"provider":"email"}','{"display_name":"User 2"}',now(),now()),
('a7150000-0000-4000-8000-000000000004','pins-3@example.test','{"provider":"email"}','{"display_name":"User 3"}',now(),now());
INSERT INTO public.groups(id,name,created_by) VALUES('a7150000-0000-4000-8000-000000000005','Pin fixture','a7150000-0000-4000-8000-000000000001'),('a7150000-0000-4000-8000-000000000006','Other fixture','a7150000-0000-4000-8000-000000000004');
INSERT INTO public.memberships(group_id,user_id,role,nickname) VALUES
('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000001','owner','Owner'),('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000002','member','Member'),('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000003','member','Third'),('a7150000-0000-4000-8000-000000000006','a7150000-0000-4000-8000-000000000004','owner','Outsider');
INSERT INTO public.messages(id,group_id,sender_id,client_id,body) VALUES
('a7150000-0000-4000-8000-000000000007','a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000002',gen_random_uuid(),'Important note'),('a7150000-0000-4000-8000-000000000008','a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000001',gen_random_uuid(),'Replacement note'),('a7150000-0000-4000-8000-000000000009','a7150000-0000-4000-8000-000000000006','a7150000-0000-4000-8000-000000000004',gen_random_uuid(),'Other group secret');
INSERT INTO public.shared_files(id,group_id,uploader_id,file_name,mime_type,size_bytes,storage_path,allow_downloads) VALUES('a7150000-0000-4000-8000-000000000010','a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000001','notes.txt','text/plain',12,'a7150000-0000-4000-8000-000000000005/a7150000-0000-4000-8000-000000000001/notes',false);
SELECT ok(NOT has_function_privilege('anon','public.group_pinned_items(uuid)','EXECUTE'),'anonymous cannot read pins');
SELECT ok(NOT has_table_privilege('authenticated','public.group_pins','INSERT,UPDATE,DELETE'),'direct writes cannot bypass permissions');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000002',true);
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000007',NULL,false)$$,'member pins for themselves');
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000007',NULL,false)$$,'pin retry is idempotent');
SELECT is(jsonb_array_length(public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'),1,'personal pin is stored once');
SELECT is((public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->>'can_pin_for_everyone')::boolean,false,'member has no shared pin permission');
SELECT throws_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000008',NULL,true)$$,'42501','not_an_owner','member cannot create shared pin');
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000003',true);
SELECT is(jsonb_array_length(public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'),0,'another member cannot see personal pin through RPC');
SELECT is((SELECT count(*)::int FROM public.group_pins),0,'RLS also hides personal pins');
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000007',NULL,false)$$,'members can pin the same message independently');
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000001',true);
SELECT is(jsonb_array_length(public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'),0,'owner cannot see other members personal pins');
SELECT is((SELECT count(*)::int FROM public.group_pins),0,'owner has no RLS bypass for personal pins');
RESET ROLE;
SELECT set_config('test.member_pin',(SELECT id::text FROM public.group_pins WHERE pinned_by='a7150000-0000-4000-8000-000000000002' AND message_id='a7150000-0000-4000-8000-000000000007'),true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.unpin_group_item('a7150000-0000-4000-8000-000000000005',current_setting('test.member_pin')::uuid)$$,'42501','pin_remove_forbidden','owner cannot remove another users personal pin');
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000007',NULL,true)$$,'owner pins for everyone');
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000007',NULL,true)$$,'shared pin retry is idempotent');
SELECT is(jsonb_array_length(public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'),1,'owner sees shared pin only');
SELECT is((public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->>'can_pin_for_everyone')::boolean,true,'owner capability returned even without personal pins');
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000007',NULL,false)$$,'owner can separately pin the shared message for themselves');
SELECT is(jsonb_array_length(public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'),2,'personal and shared pins coexist');
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000002',true);
SELECT is(jsonb_array_length(public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'),2,'member sees own pin and shared pin only');
SELECT is((SELECT count(*)::int FROM public.group_pins),2,'RLS exposes own and shared rows only');
SELECT is((public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'->0->>'can_unpin')::boolean,false,'member cannot remove shared pin');
SELECT throws_ok($$SELECT public.unpin_group_item('a7150000-0000-4000-8000-000000000005',(SELECT id FROM public.group_pins WHERE pinned_by='a7150000-0000-4000-8000-000000000001' AND visibility='group' AND message_id='a7150000-0000-4000-8000-000000000007'))$$,'42501','pin_remove_forbidden','server enforces shared unpin ownership');
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000001',true);
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000008',NULL,true)$$,'owner replaces shared pin');
SELECT is((SELECT count(*)::int FROM public.group_pins WHERE visibility='group' AND active),1,'only one active group pin');
SELECT is(public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'->0->'message'->>'body','Replacement note','replacement is current shared pin');
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000002',true);
SELECT is(jsonb_array_length(public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'),2,'replacement preserves personal pin');
SELECT lives_ok($$SELECT public.unpin_group_item('a7150000-0000-4000-8000-000000000005',current_setting('test.member_pin')::uuid)$$,'member removes own personal pin');
SELECT lives_ok($$SELECT public.unpin_group_item('a7150000-0000-4000-8000-000000000005',current_setting('test.member_pin')::uuid)$$,'unpin retry is idempotent');
SELECT is(jsonb_array_length(public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'),1,'personal removal leaves shared pin');
SELECT throws_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000009',NULL,false)$$,'P0002','pin_target_missing','cannot pin a different groups message');
SELECT throws_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005',NULL,NULL,false)$$,'22023','pin_target_invalid','missing target rejected');
SELECT throws_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000007','a7150000-0000-4000-8000-000000000010',false)$$,'22023','pin_target_invalid','ambiguous targets rejected');
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000004',true);
SELECT is((SELECT count(*)::int FROM public.group_pins),0,'outsider sees no pins in RLS');
SELECT throws_ok($$SELECT public.group_pinned_items('a7150000-0000-4000-8000-000000000005')$$,'42501','not_a_member','outsider cannot read pins');
SELECT throws_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000007',NULL,false)$$,'42501','not_a_member','outsider cannot pin');
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000001',true);
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005',NULL,'a7150000-0000-4000-8000-000000000010',true)$$,'owner can pin attachment');
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000002',true);
SELECT is((public.group_pinned_items('a7150000-0000-4000-8000-000000000005')->'items'->0->'file'->>'allow_downloads')::boolean,false,'pinned attachments keep download restriction');
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005',NULL,'a7150000-0000-4000-8000-000000000010',false)$$,'member can also pin an attachment privately');
RESET ROLE;
DELETE FROM public.shared_files WHERE id='a7150000-0000-4000-8000-000000000010';
SELECT is((SELECT count(*)::int FROM public.group_pins WHERE file_id='a7150000-0000-4000-8000-000000000010'),0,'deleting attachment removes every related pin');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000001',true);
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000008',NULL,true)$$,'owner restores shared text pin');
SELECT lives_ok($$SELECT public.transfer_group_and_leave('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000002')$$,'transfer owner and leave');
SELECT throws_ok($$SELECT public.group_pinned_items('a7150000-0000-4000-8000-000000000005')$$,'42501','not_a_member','former member cannot read stored pins');
SELECT set_config('request.jwt.claim.sub','a7150000-0000-4000-8000-000000000002',true);
SELECT lives_ok($$SELECT public.unpin_group_item('a7150000-0000-4000-8000-000000000005',(SELECT id FROM public.group_pins WHERE pinned_by='a7150000-0000-4000-8000-000000000001' AND visibility='group' AND message_id='a7150000-0000-4000-8000-000000000008'))$$,'new owner can remove former owners shared pin');
SELECT lives_ok($$SELECT public.pin_group_item('a7150000-0000-4000-8000-000000000005','a7150000-0000-4000-8000-000000000008',NULL,true)$$,'new owner can create shared pin');
RESET ROLE;
DELETE FROM public.groups WHERE id='a7150000-0000-4000-8000-000000000005';
SELECT is((SELECT count(*)::int FROM public.group_pins WHERE group_id='a7150000-0000-4000-8000-000000000005'),0,'dissolution removes personal and shared pins');
SELECT * FROM finish();
ROLLBACK;
